+}
+
+function drawRanking() {
+  const x = 70, y = 535, w = 1460, h = 910;
+  rect(x, y, w, h, { rx: 10, fill: "url(#panelGrad)", stroke: "#21405E", strokeWidth: 1.4 });
+  sectionTitle("Top Models by Accuracy", x + 34, y + 64, "Ranked by percent correct across the 225-task polyglot benchmark");
