+  text("Edit", col.format, headerY, { size: 16, weight: 780, fill: colors.faint, spacing: 1.4, class: "label" });
+  text("Percent Correct", col.bar, headerY, { size: 16, weight: 780, fill: colors.faint, spacing: 1.4, class: "label" });
+  text("Score", col.score, headerY, { size: 16, weight: 780, fill: colors.faint, spacing: 1.4, class: "label" });
